package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.EnumResolver;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.math.*;
import java.net.URI;
import java.net.URL;
import java.util.*;
import java.util.Calendar;
import java.util.Currency;
import java.util.Date;
import java.util.Locale;
import java.util.UUID;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for StdKeyDeserializer.forType(Class<?> raw)
 */
public class StdKeyDeserializer_forType_TriageGen2Test {

    // Constants copied from the context to allow assertion of the returned object state
    // Note: In a real Jackson environment, these are internal constants.
    private static final int TYPE_UUID = 1; // Assuming these values based on the logic provided
    private static final int TYPE_INT = 2;
    private static final int TYPE_LONG = 3;
    private static final int TYPE_DATE = 4;
    private static final int TYPE_CALENDAR = 5;
    private static final int TYPE_BOOLEAN = 6;
    private static final int TYPE_BYTE = 7;
    private static final int TYPE_CHAR = 8;
    private static final int TYPE_SHORT = 9;
    private static final int TYPE_FLOAT = 10;
    private static final int TYPE_DOUBLE = 11;
    private static final int TYPE_URI = 12;
    private static final int TYPE_URL = 13;
    private static final int TYPE_CLASS = 14;
    private static final int TYPE_LOCALE = 15;
    private static final int TYPE_CURRENCY = 16;

    @Test
    public void testForType_StringAndObject() {
        // String and Object are handled by StringKD.forType(raw)
        // We verify they don't return null
        StdKeyDeserializer stringDeser = StdKeyDeserializer.forType(String.class);
        assertNotNull(stringDeser);
        assertEquals(String.class, stringDeser.getKeyClass());

        StdKeyDeserializer objectDeser = StdKeyDeserializer.forType(Object.class);
        assertNotNull(objectDeser);
        assertEquals(Object.class, objectDeser.getKeyClass());
    }

    @Test
    public void testForType_CommonTypes() {
        assertNotNull(StdKeyDeserializer.forType(UUID.class));
        assertEquals(UUID.class, StdKeyDeserializer.forType(UUID.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Integer.class));
        assertEquals(Integer.class, StdKeyDeserializer.forType(Integer.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Long.class));
        assertEquals(Long.class, StdKeyDeserializer.forType(Long.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Date.class));
        assertEquals(Date.class, StdKeyDeserializer.forType(Date.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Calendar.class));
        assertEquals(Calendar.class, StdKeyDeserializer.forType(Calendar.class).getKeyClass());
    }

    @Test
    public void testForType_LessCommonTypes() {
        assertNotNull(StdKeyDeserializer.forType(Boolean.class));
        assertEquals(Boolean.class, StdKeyDeserializer.forType(Boolean.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Byte.class));
        assertEquals(Byte.class, StdKeyDeserializer.forType(Byte.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Character.class));
        assertEquals(Character.class, StdKeyDeserializer.forType(Character.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Short.class));
        assertEquals(Short.class, StdKeyDeserializer.forType(Short.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Float.class));
        assertEquals(Float.class, StdKeyDeserializer.forType(Float.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Double.class));
        assertEquals(Double.class, StdKeyDeserializer.forType(Double.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(URI.class));
        assertEquals(URI.class, StdKeyDeserializer.forType(URI.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(URL.class));
        assertEquals(URL.class, StdKeyDeserializer.forType(URL.class).getKeyClass());

        assertNotNull(StdKeyDeserializer.forType(Class.class));
        assertEquals(Class.class, StdKeyDeserializer.forType(Class.class).getKeyClass());
    }

    @Test
    public void testForType_WithFromStringDeserializer() {
        // Testing Locale branch
        StdKeyDeserializer localeDeser = StdKeyDeserializer.forType(Locale.class);
        assertNotNull(localeDeser);
        assertEquals(Locale.class, localeDeser.getKeyClass());

        // Testing Currency branch
        StdKeyDeserializer currencyDeser = StdKeyDeserializer.forType(Currency.class);
        assertNotNull(currencyDeser);
        assertEquals(Currency.class, currencyDeser.getKeyClass());
    }

    @Test
    public void testForType_NullReturn() {
        // Test an unsupported type to trigger the 'else { return null; }' branch
        StdKeyDeserializer unknownDeser = StdKeyDeserializer.forType(Double.class.getEnclosingClass()); 
        // Using a class that isn't in the list, e.g., a custom class or just a generic non-matching one
        assertNull(StdKeyDeserializer.forType(Thread.class));
    }
}
